import {useCallback,useEffect,useRef,useState} from 'react';
import './list.css';
type Item={id:string;title:string};
export function ListWorkspace({load,onCreate}:{load:(signal:AbortSignal)=>Promise<Item[]>;onCreate:()=>void}){
 const [items,setItems]=useState<Item[]|null>(null),[pending,setPending]=useState(true),[error,setError]=useState<string|null>(null);
 const request=useRef<AbortController|null>(null);
 const refresh=useCallback(async()=>{request.current?.abort();const controller=new AbortController();request.current=controller;setPending(true);setError(null);try{const result=await load(controller.signal);if(!controller.signal.aborted)setItems(result)}catch(e){if(!controller.signal.aborted)setError(e instanceof Error?e.message:'Please try again.')}finally{if(!controller.signal.aborted)setPending(false)}},[load]);
 useEffect(()=>{void refresh();return()=>request.current?.abort()},[refresh]);
 return <section className="list-workspace" aria-labelledby="list-title"><header><h1 id="list-title">Items</h1><button disabled={pending} onClick={()=>void refresh()}>Refresh</button></header><p role="status">{pending?(items===null?'Loading items…':'Refreshing… Existing items remain available.'):(error?'':items?.length===0?'No items yet.':String(items?.length??0)+' items')}</p>{error&&<div role="alert" className="list-error"><strong>{items===null?'Could not load items.':'Could not refresh items. Showing the last loaded results.'}</strong><p>{error}</p><button onClick={()=>void refresh()}>Try again</button></div>}<div aria-busy={pending}>{items?.length===0&&<div className="list-empty"><h2>Your list is empty</h2><p>Create an item to get started.</p><button onClick={onCreate}>Create item</button></div>}{items!==null&&items.length>0&&<ul>{items.map(item=><li key={item.id}>{item.title}</li>)}</ul>}</div></section>;
}
